<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/functions.php';require_role(['admin']);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$role=$_POST['role']??'customer';if(!$id||$username===''||$email===''||!in_array($role,['admin','employee','customer'],true))$error='Username, email, and a valid role are required.';elseif($id===(int)current_user()['id']&&$role!=='admin')$error='You cannot remove your own admin role while signed in.';else{try{$st=$pdo->prepare('UPDATE users SET full_name=?,username=?,email=?,phone=?,address=?,role=? WHERE id=?');$st->execute([$name,$username,$email,$phone,$address,$role,$id]);header('Location: users.php');exit;}catch(PDOException $e){$error='Email may already be used by another account.';}}}
$search=trim($_GET['q']??'');$st=$pdo->prepare("SELECT id,username,email,role,created_at,full_name,phone,address FROM users WHERE username LIKE ? OR email LIKE ? OR COALESCE(full_name,'') LIKE ? OR COALESCE(phone,'') LIKE ? ORDER BY created_at DESC");$like='%'.$search.'%';$st->execute([$like,$like,$like,$like]);$users=$st->fetchAll();$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT id,username,email,role,created_at,full_name,phone,address FROM users WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}$history=[];if(isset($_GET['history'])){$st=$pdo->prepare('SELECT id,total,status,created_at FROM orders WHERE user_id=? ORDER BY created_at DESC');$st->execute([(int)$_GET['history']]);$history=$st->fetchAll();}$pageTitle='User Management';include __DIR__.'/../includes/header.php';?>
<div class="admin-shell"><h1>USER MANAGEMENT</h1><nav class="admin-nav"><a href="index.php">Dashboard</a><a href="products.php">Products</a><a href="categories.php">Categories</a><a href="suppliers.php">Suppliers</a><a href="inventory.php">Inventory</a><a href="users.php">Users</a><a href="reports.php">Reports & Expenses</a></nav><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?>
<form method="get" class="inline-form" style="margin:20px 0"><input name="q" placeholder="Search name, username, email, phone" value="<?=e($search)?>"><button class="btn btn-blue">SEARCH USERS</button><a class="btn" href="users.php">Clear</a></form>
<?php if($edit):?><section class="form-wrap" style="margin:20px 0;max-width:760px"><h2>Edit user record</h2><form method="post"><input type="hidden" name="id" value="<?=$edit['id']?>"><div class="field"><label>Full name</label><input name="full_name" value="<?=e($edit['full_name']??'')?>"></div><div class="field"><label>Username</label><input name="username" required value="<?=e($edit['username'])?>"></div><div class="field"><label>Email</label><input type="email" name="email" required value="<?=e($edit['email'])?>"></div><div class="field"><label>Phone</label><input name="phone" value="<?=e($edit['phone']??'')?>"></div><div class="field"><label>Address</label><textarea name="address"><?=e($edit['address']??'')?></textarea></div><div class="field"><label>Role</label><select name="role"><?php foreach(['customer','employee','admin'] as $r):?><option value="<?=$r?>" <?=$edit['role']===$r?'selected':''?>><?=ucfirst($r)?></option><?php endforeach;?></select></div><button class="btn btn-blue">UPDATE USER</button> <a class="btn" href="users.php">Cancel</a></form></section><?php endif;?>
<?php if(isset($_GET['history'])):?><h2>User order history</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td>#<?=$h['id']?></td><td><?=e($h['created_at'])?></td><td><?=money($h['total'])?></td><td><?=e($h['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
<h2>User records</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Name / Username</th><th>Email</th><th>Phone</th><th>Created</th><th>Role</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['full_name']?:$u['username'])?><br><small><?=e($u['username'])?></small></td><td><?=e($u['email'])?></td><td><?=e($u['phone']??'')?></td><td><?=e($u['created_at'])?></td><td><?=e($u['role'])?></td><td><a href="users.php?edit=<?=$u['id']?>">Edit</a> | <a href="users.php?history=<?=$u['id']?>">History</a></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php';?>